pub(super) static ROWS_0: &[RawRow] = &[
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-butter-and-margarine", domain: "differences", reply: "Butter is churned cream; margarine is refined vegetable oil blended with water and flavouring, made to spread and bake like butter. Butter tastes better and browns better, margarine is cheaper and spreadable straight from the fridge.", key: &[&["butter"],&["margarine"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-single-cream-and-double-cream", domain: "differences", reply: "Single cream is about 18% fat and only pours; double cream is about 48% and whips, thickens and holds its shape. Use single for pouring over a pudding and double where it has to whip or survive being boiled.", key: &[&["single cream"],&["double cream"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-soured-cream-and-creme-fraiche", domain: "differences", reply: "Sour cream is about 20% fat and sours with lactic acid, so it splits if you boil it; creme fraiche is thicker, about 30% fat, and can be boiled without splitting. Stir sour cream in off the heat, and use creme fraiche for a sauce that simmers.", key: &[&["soured cream", "sour cream"],&["creme fraiche", "crème fraîche"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-gammon-and-ham", domain: "differences", reply: "Gammon is the cut before it is cooked - a cured hind leg of pork - and ham is what you call it once it's cooked or sold ready to eat. You buy gammon to roast, and ham to put in a sandwich.", key: &[&["gammon"],&["ham"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-yam-and-sweet-potato", domain: "differences", reply: "A true yam is a rough, bark-like tuber from Africa and Asia, drier and starchier; the orange or white-fleshed \"yam\" in most UK shops is a sweet potato. If it has smooth skin, it's a sweet potato.", key: &[&["yam", "yams"],&["sweet potato", "sweet potatoes"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-shallot-and-onion", domain: "differences", reply: "A shallot is a small, mild relative of the onion, grown in cloves, sweeter and gentler raw. Use shallots where you want onion flavour without the bite - dressings, sauces, or roasted whole.", key: &[&["shallot", "shallots"],&["onion", "onions"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-stock-cube-and-stock-pot", domain: "differences", reply: "A stock cube is dried concentrate, about one per 450ml of water, and salty. A stock pot is wet ready-made stock in a tub - fresher tasting and less salty - used one pot to roughly 500ml. Either is fine; taste before you season.", key: &[&["stock cube", "stock cubes"],&["stock pot", "stock pots", "fresh stock"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-plain-flour-and-self-raising-flour", domain: "differences", reply: "Self-raising flour has baking powder already in it, about two teaspoons for every 150g of flour; plain flour has none. Cakes and scones want self-raising, bread and pastry want plain - and you can make self-raising by adding the baking powder yourself.", key: &[&["plain flour"],&["self raising flour", "self-raising flour"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-baking-soda-and-baking-powder", domain: "differences", reply: "Baking soda is pure bicarbonate of soda and needs an acid - buttermilk, lemon, yoghurt - to make something rise. Baking powder is bicarbonate with the acid already mixed in, so it works with plain liquid and is what most cake recipes mean. To swap them, use about three times as much baking powder as soda, and never the other way round.", key: &[&["baking soda", "bicarbonate of soda", "bicarb"],&["baking powder"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-calorie-and-kilojoule", domain: "differences", reply: "A calorie is the unit most food labels in the UK still lead with; a kilojoule is the metric one, usually in brackets beside it. One calorie is about 4.2 kilojoules, so 500 kcal is roughly 2,100 kJ.", key: &[&["calorie", "calories", "kcal"],&["kilojoule", "kilojoules", "kj"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-tax-credit-and-benefit", domain: "differences", reply: "A benefit is money from the government because of your circumstances or your income; a tax credit was an older means-tested benefit paid through the tax system, and most people on them are being moved to Universal Credit. If you're not sure which you're on, your award letter says.", key: &[&["tax credit", "tax credits"],&["benefit", "benefits"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-holding-deposit-and-deposit", domain: "differences", reply: "A holding deposit is the small sum - at most a week's rent in England - that takes a place off the market while the landlord checks you. The tenancy deposit is the bigger amount you pay when you sign, and it has to be held in a government protection scheme.", key: &[&["holding deposit"],&["deposit", "tenancy deposit", "security deposit"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-interest-rate-and-apr", domain: "differences", reply: "The interest rate is what you pay on the money you owe; the APR also folds in the fees, so it's the number to compare two loans by. The lower APR is the cheaper loan, as long as the term is the same.", key: &[&["interest rate"],&["apr"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-credit-score-and-credit-report", domain: "differences", reply: "The report is the file itself - your accounts, payments and any defaults, as lenders see them. The score is a number one agency makes out of that file. Check the report for mistakes, because the score only follows from it.", key: &[&["credit score"],&["credit report", "credit file"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-sole-trader-and-limited-company", domain: "differences", reply: "A sole trader is you and the business as one: simplest to run, but you're personally liable for its debts. A limited company is a separate legal person, so your own money is protected if it fails, and in exchange you file accounts publicly at Companies House.", key: &[&["sole trader"],&["limited company", "ltd"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-third-party-and-comprehensive", domain: "differences", reply: "Third party covers the damage you do to other people and their cars; comprehensive adds damage to your own car, fire and theft. Third party, fire and theft sits between them - cheaper than comprehensive, but your own car is only covered if it burns or is stolen.", key: &[&["third party", "third party fire and theft"],&["comprehensive"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-pcp-and-hire-purchase", domain: "differences", reply: "PCP is a loan with a final balloon payment: you pay mostly for the car's fall in value, then hand it back, pay the lump sum, or trade it in. Hire purchase spreads the whole price over the term, and the car is yours after the last payment.", key: &[&["pcp", "personal contract purchase"],&["hire purchase"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-psychiatrist-and-psychologist", domain: "differences", reply: "A psychiatrist is a doctor who can diagnose mental illness and prescribe medicine; a psychologist studies and treats the mind with talking therapy and usually can't prescribe. A GP can refer you to either, and which one you need depends on whether medicine is part of the question.", key: &[&["psychiatrist"],&["psychologist"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-counsellor-and-therapist", domain: "differences", reply: "In the UK the words are used much the same way - someone trained to listen and help you work something through. \"Therapist\" is the broader word and covers CBT and other set approaches; \"counsellor\" usually means a trained listener rather than a clinician. Neither title is protected by law, so check the person is accredited.", key: &[&["counsellor", "counselor"],&["therapist", "psychotherapist"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-anxiety-and-panic-attack", domain: "differences", reply: "Anxiety is the background feeling - worry and tension over days and weeks; a panic attack is a short, sudden surge that peaks within minutes, with a racing heart, breathlessness and a feeling that something awful is about to happen. You can have either without the other, and both are treatable.", key: &[&["anxiety"],&["panic attack", "panic attacks"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-migraine-and-headache", domain: "differences", reply: "A headache is pain in the head; a migraine is a condition - usually one-sided, throbbing, worse with light or movement, often with nausea or a warning aura, lasting hours. If a headache sends you to a dark room more than once, it's worth asking a GP about migraine.", key: &[&["migraine", "migraines"],&["headache", "headaches"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-heart-attack-and-cardiac-arrest", domain: "differences", reply: "A heart attack is a blocked blood supply to the heart muscle - the person is usually awake, with chest pain, and needs an ambulance fast. A cardiac arrest is the heart stopping altogether: unresponsive and not breathing normally, needing CPR and a defibrillator at once - call 999 first.", key: &[&["heart attack"],&["cardiac arrest"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-food-allergy-and-intolerance", domain: "differences", reply: "An allergy is the immune system reacting to a food: it can come on within minutes and can be dangerous, with swelling or trouble breathing, so it means strict avoidance. An intolerance is the body struggling to digest something - uncomfortable, but not dangerous - and lactose is the common one.", key: &[&["food allergy", "allergy"],&["intolerance", "food intolerance"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-cold-sore-and-mouth-ulcer", domain: "differences", reply: "A cold sore is the herpes virus: a tingle, then a blister, usually on the lip, crusting over in a week or so, and it's catching. A mouth ulcer is a raw round sore inside the mouth, not catching, often from a knock, stress or a sharp tooth.", key: &[&["cold sore", "cold sores"],&["mouth ulcer", "mouth ulcers"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-hay-fever-and-cold", domain: "differences", reply: "Hay fever is an allergy to pollen - sneezing, itchy eyes and a runny nose, no temperature, and it comes back at the same time each year. A cold is an infection: a sore throat first, then a blocked nose, gone in about a week.", key: &[&["hay fever", "hayfever"],&["cold", "a cold"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-boil-and-cyst", domain: "differences", reply: "A boil is an infection of a hair follicle - tender and hot, and it comes to a head and drains. A cyst is a closed sac under the skin, usually painless unless it gets inflamed, and it doesn't drain by itself. Neither should be squeezed.", key: &[&["boil", "boils"],&["cyst", "cysts"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-hypo-and-hyper", domain: "differences", reply: "A hypo is low blood sugar - shaky, sweaty, confused - and it needs sugar fast. Hyper means high: thirsty, weeing a lot, tired over hours, and it needs insulin and advice. The hypo is the one that has to be treated in minutes.", key: &[&["hypo", "hypoglycaemia", "low blood sugar"],&["hyper", "hyperglycaemia", "high blood sugar"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-flu-and-covid", domain: "differences", reply: "Flu is influenza and Covid is the coronavirus, and you can't tell them apart by symptoms - fever, cough and tiredness come with both, so a test is the only way to know. Both are worth staying home for, and both are riskier for the same people.", key: &[&["flu", "influenza"],&["covid", "coronavirus"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-state-school-and-academy", domain: "differences", reply: "Both are state schools and free to attend. A maintained school is run by the local authority; an academy is funded directly by the government, sets its own curriculum and admissions, and is run by a trust. For a parent, the practical difference is who you complain to.", key: &[&["state school"],&["academy", "academies", "free school"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-apprenticeship-and-traineeship", domain: "differences", reply: "An apprenticeship is a paid job with training and a qualification, usually one to four years. A traineeship is a short unpaid course - weeks, not years - for someone not yet ready for an apprenticeship, and it's often the step before one.", key: &[&["apprenticeship", "apprenticeships"],&["traineeship", "traineeships"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-btec-and-a-level", domain: "differences", reply: "A levels are exam-based and mostly academic, usually three subjects; BTECs are coursework-based and vocational, and a full BTEC is the size of three A levels. Both get you to university, and a BTEC suits a subject you'd rather do than read about.", key: &[&["btec", "btecs"],&["a level", "a levels"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-cv-and-cover-letter", domain: "differences", reply: "A CV lists what you've done - jobs, education, skills - in a page or two. A cover letter is the short note that goes with it, saying why you want this job and which bits of the CV matter for it.", key: &[&["cv"],&["cover letter", "covering letter"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-mortgage-broker-and-financial-adviser", domain: "differences", reply: "A broker shops mortgages from several lenders for you and is paid a fee or commission. A financial adviser looks at the whole picture - pensions, savings, investments - and is regulated to advise on them. Use the broker for the mortgage and the adviser for the rest.", key: &[&["mortgage broker", "broker"],&["financial adviser", "financial advisor", "ifa"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-letting-agent-and-landlord", domain: "differences", reply: "The landlord owns the place; the letting agent runs it for them - viewings, repairs, the paperwork. Your tenancy is with the landlord, so your rights are against the owner even when you deal with the agent every day.", key: &[&["letting agent"],&["landlord"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-solicitor-and-barrister", domain: "differences", reply: "A solicitor is who you deal with directly: contracts, conveyancing, wills, letters, and preparing a case. A barrister is the court specialist who argues it in front of a judge, and a solicitor usually instructs them for you.", key: &[&["solicitor"],&["barrister"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-optician-and-optometrist", domain: "differences", reply: "The optometrist tests your eyes and writes the prescription; the dispensing optician makes and fits the glasses. Most high-street shops are both, so you see whoever your appointment is with.", key: &[&["optician", "opticians"],&["optometrist", "optometrists"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-dentist-and-hygienist", domain: "differences", reply: "The dentist diagnoses and treats - check-ups, fillings, crowns, extractions; the hygienist cleans, scaling and polishing and checking your gums. Most practices book you with the hygienist every six months and the dentist for the check-up.", key: &[&["dentist"],&["hygienist", "dental hygienist"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-tablet-and-laptop", domain: "differences", reply: "A tablet is a touchscreen for reading, watching and browsing; a laptop has a keyboard and full software, so it's the one for typing, spreadsheets and real work. If it's your only device for work, get the laptop.", key: &[&["tablet", "tablets", "ipad"],&["laptop", "laptops", "computer"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-smart-meter-and-normal-meter", domain: "differences", reply: "A smart meter sends your readings to the supplier itself, so you stop reading meters, and it comes with an in-home display. An old meter needs reading by you or a visitor. Neither changes what you pay per unit.", key: &[&["smart meter"],&["normal meter", "old meter", "traditional meter"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-dehumidifier-and-air-purifier", domain: "differences", reply: "A dehumidifier takes water out of the air, which is what stops damp, condensation and mould; an air purifier filters dust, pollen and smoke out of it. Damp room, dehumidifier; allergies or a smoky street, purifier.", key: &[&["dehumidifier"],&["air purifier"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-celsius-and-fahrenheit", domain: "differences", reply: "Celsius freezes water at 0 and boils it at 100; Fahrenheit puts the same two marks at 32 and 212, so a Fahrenheit degree is the smaller one. To convert, multiply the Celsius figure by 1.8 and add 32 - body heat is 37C or 98.6F, and a hot day is 30C or 86F.", key: &[&["celsius", "centigrade"],&["fahrenheit"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-sea-salt-and-table-salt", domain: "differences", reply: "Both are sodium chloride and season the same; sea salt is coarser and less dense, so a level teaspoon holds less of it, and table salt is fine, treated to run freely and has iodine added in the UK. Use table salt in baking, where it has to dissolve evenly.", key: &[&["sea salt"],&["table salt"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-whole-milk-and-semi-skimmed-milk", domain: "differences", reply: "Whole milk is about 3.5% fat, semi-skimmed about 1.7% and skimmed under 0.5%. Semi-skimmed has roughly half the fat and calories of whole, and the protein and calcium are much the same, so for most adults it is the swap that costs nothing.", key: &[&["whole milk"],&["semi skimmed milk", "semi-skimmed milk", "skimmed milk"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-eczema-and-psoriasis", domain: "differences", reply: "Eczema is dry, itchy, red skin, often in the elbow and knee creases, and it flares with soap, heat and stress. Psoriasis makes thick, silvery scaly patches, usually on elbows, knees and scalp, and it can affect the joints too. Both are treated with emollients and steroid creams, so a GP or pharmacist is the place to start.", key: &[&["eczema"],&["psoriasis"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-stress-and-burnout", domain: "differences", reply: "Stress is too much pressure while you can still see the point of what you are doing; burnout is the exhaustion that comes after months of it, when you have stopped caring and the work feels flat. Stress eases when the pressure does - burnout does not, and usually needs time off and a change, not a better week.", key: &[&["stress"],&["burnout", "burn out", "burn-out"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-fixed-rate-and-variable-rate", domain: "differences", reply: "A fixed rate stays the same for an agreed term, so the monthly payment is known from the start; a variable rate moves with the lender or the Bank of England and can fall as well as rise. Fixed buys certainty and usually costs a little more; variable is cheaper while rates are falling.", key: &[&["fixed rate", "fixed"],&["variable rate", "variable"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-lodger-and-tenant", domain: "differences", reply: "A lodger lives in the same home as the owner and shares the kitchen or bathroom; a tenant rents a place of their own with a tenancy and has the whole of it. A lodger can usually be asked to leave with reasonable notice, while a tenant needs a court order - so in England the word on the agreement matters as much as the money.", key: &[&["lodger", "lodgers"],&["tenant", "tenants"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-food-processor-and-blender", domain: "differences", reply: "A blender is a tall jug with blades in the base, for things that pour - smoothies, soup, sauces. A food processor is a wide bowl with a blade and discs, for chopping, slicing and grating solid food like onions, nuts or pastry. Thin and liquid, blender; chunky or grated, processor.", key: &[&["food processor"],&["blender"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-coach-and-bus", domain: "differences", reply: "A bus is the local service, stopping often along a town route and often turning up without a booking; a coach is for longer journeys between towns, with seats booked in advance, luggage in the hold and few stops. In the UK, National Express and Megabus run coaches.", key: &[&["coach", "coaches"],&["bus", "buses"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-shark-and-dolphin", domain: "differences", reply: "A shark is a fish: gills, cartilage instead of bone, and a tail that swings side to side. A dolphin is a mammal: it breathes air through a blowhole, has a skeleton, feeds its young milk, and its tail moves up and down.", key: &[&["shark", "sharks"],&["dolphin", "dolphins"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:295
    RawRow { id: "difference-moth-and-butterfly", domain: "differences", reply: "Butterflies mostly fly by day and rest with their wings folded up together; moths mostly fly at night and rest with theirs spread flat. Moths also have fatter, hairier bodies and feathery antennae rather than thin ones with a club on the end.", key: &[&["moth", "moths"],&["butterfly", "butterflies"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/differences.py:303
    RawRow { id: "difference-single-or-double-cream", domain: "differences", reply: "Single cream is about 18% fat and only pours; double cream is about 48% and whips, thickens and holds its shape. Use single for pouring over a pudding and double where it has to whip or survive being boiled.", key: &[&["single"],&["double"],], grouped: true, avoid: &[], ask: &[&["difference"],&["different"],&["differ"],&["versus"],&["vs"],&["compare"],&["compared"],&["distinguish"],&["same"],], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Text(|reading| { let _ = reading; (({ let text = reading.line.clean.clone(); if text.is_empty() { "".to_owned() } else { text } }).to_lowercase()).contains("cream") }), callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
];
